package Zram::Config::Parser;

use strict;
use warnings;

use Exporter qw(import);
use Zram::Error qw(fatal);

our @EXPORT_OK = qw(parse_file);

use constant MAX_CONFIG_BYTES => 65_536;
use constant MAX_CONFIG_LINE_BYTES => 4_096;

sub _trim {
    my ($value) = @_;
    $value =~ s/\A\s+//;
    $value =~ s/\s+\z//;
    return $value;
}

sub _parse_value {
    my ($label, $value) = @_;
    $value = _trim($value);
    if ($value =~ /\A"(.*)"\z/s) {
        $value = $1;
        $value =~ s/\\(["\\])/$1/g;
    } elsif ($value =~ /\A'(.*)'\z/s) {
