sub _flatten {
    my ($prefix, $value, $out) = @_;
    if (ref($value) eq 'HASH') {
        for my $key (sort keys %{$value}) {
            my $next = $prefix eq '' ? $key : "$prefix.$key";
            _flatten($next, $value->{$key}, $out);
