        qr/\b(?:ZRAM_PRESSURE|ZRAM_COLD_TIER|ZRAM_IDLE_WRITEBACK|ZRAM_DAEMON|ZRAM_HOT_AGE|ZRAM_DAILY_WRITEBACK_LIMIT|ZRAM_MAINTENANCE|ZRAM_MIN_FREE_MEMORY|ZRAM_WRITEBACK_MIN_REMAINING)/,
