sub merge_defaults {
    my ($input) = @_;
    my $merged = default_config();
    for my $section (keys %{$input}) {
        $merged->{$section} ||= {};
        for my $key (keys %{$input->{$section}}) {
            $merged->{$section}{$key} = $input->{$section}{$key};
