   850	validate_distinct_recompression_priorities() {
   851	  if [ "$ZRAM_TIER1_ENABLE" -eq 1 ] &&
   852	     [ "$ZRAM_TIER2_ENABLE" -eq 1 ] &&
   853	     [ "$ZRAM_TIER1_PRIORITY" -eq "$ZRAM_TIER2_PRIORITY" ]; then
   854	    fatal "enabled recompression tiers 1 and 2 must not share priority ${ZRAM_TIER1_PRIORITY}"
