   857	     [ "$ZRAM_TIER3_ENABLE" -eq 1 ] &&
   858	     [ "$ZRAM_TIER1_PRIORITY" -eq "$ZRAM_TIER3_PRIORITY" ]; then
   859	    fatal "enabled recompression tiers 1 and 3 must not share priority ${ZRAM_TIER1_PRIORITY}"
