   861	  if [ "$ZRAM_TIER2_ENABLE" -eq 1 ] &&
   862	     [ "$ZRAM_TIER3_ENABLE" -eq 1 ] &&
   863	     [ "$ZRAM_TIER2_PRIORITY" -eq "$ZRAM_TIER3_PRIORITY" ]; then
   864	    fatal "enabled recompression tiers 2 and 3 must not share priority ${ZRAM_TIER2_PRIORITY}"
